from typing import List


class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        n = len(strength)
        full = 1 << n
        dp = [float("inf")] * full
        dp[0] = 0
        for mask in range(full):
            if dp[mask] == float("inf"):
                continue
            factor = 1 + K * bin(mask).count("1")
            for i in range(n):
                if not mask & (1 << i):
                    cost = (strength[i] + factor - 1) // factor
                    nxt = mask | (1 << i)
                    dp[nxt] = min(dp[nxt], dp[mask] + cost)
        return dp[full - 1]

